#include <semantics/entities/state_store.hpp>
#include <mutex>
namespace rebuntu::model { void StateStore::upsert(Fact f){std::unique_lock l(mu_);facts_[{f.subject,f.predicate}]=std::move(f);++generation_;} std::optional<Fact> StateStore::get(const std::string&s,const std::string&p)const{std::shared_lock l(mu_);auto i=facts_.find({s,p});return i==facts_.end()?std::nullopt:std::optional<Fact>(i->second);} std::vector<Fact> StateStore::subject(const std::string&s)const{std::shared_lock l(mu_);std::vector<Fact>o;for(auto&[k,v]:facts_)if(k.first==s)o.push_back(v);return o;} std::vector<Fact> StateStore::all()const{std::shared_lock l(mu_);std::vector<Fact>o;for(auto&[k,v]:facts_)o.push_back(v);return o;} std::uint64_t StateStore::generation()const{std::shared_lock l(mu_);return generation_;} }
